var COMBAT_SCALE = 0.82;
var HERO_RENDER_SCALE = 0.78 * COMBAT_SCALE;
var BOSS_RENDER_SCALE = 1.35 * COMBAT_SCALE;
var combatDistance = (value) => value * COMBAT_SCALE;

// src/movement-fx.js
function createMovementTrail(hero, from, kind) {
  return {
    kind,
    t: 0,
    life: kind === "dodge" ? 0.52 : 0.44,
    body: posed(hero.pose(), hero.look),
    facing: hero.facing,
    from: { ...from },
    to: { x: hero.x, y: hero.y },
    color: hex(kind === "dodge" ? "#ffc36c" : "#87dfff"),
    rim: hex(kind === "dodge" ? "#fff1c1" : "#dcfaff")
  };
}
function drawMovementTrail(p, trail5) {
  const k = Math.max(0, 1 - trail5.t / trail5.life);
  if (!k) return;
  const { from, to, body: b, color, rim: rim2, facing } = trail5;
  const length = Math.hypot(to.x - from.x, to.y - from.y);
  for (let j = 0; j < 3; j++) {
    const u = j / 3, x = from.x + (to.x - from.x) * u, y = from.y + (to.y - from.y) * u;
    const alpha = k * (0.28 + j * 0.17);
    for (let i = 0; i < b.n; i++) {
      const py = Math.round(b.ys[i] * HERO_RENDER_SCALE);
      if (j === 0 && (py + Math.floor(trail5.t * 20)) % 3 === 0) continue;
      p.dot(x + b.xs[i] * HERO_RENDER_SCALE * facing, y + py, j === 2 ? rim2 : color, alpha);
    }
    p.glow(x, y - combatDistance(11), combatDistance(14), color, k * 0.1);
  }
  if (length > 1) {
    for (let i = 0; i < 3; i++) {
      const h = combatDistance(5 + i * 7);
      p.line(from.x, from.y - h, to.x, to.y - h, i === 1 ? rim2 : color, k * (0.65 - i * 0.1));
    }
    p.glowLine(from.x, from.y - combatDistance(10), to.x, to.y - combatDistance(10), combatDistance(5), color, 0.2 * k);
  }
  const r = combatDistance(3 + trail5.t * 24);
  for (const point2 of [from, to]) {
    for (let i = 0; i < 12; i++) {
      const a = i / 12 * Math.PI * 2;
      p.dot(point2.x + Math.cos(a) * r, point2.y + Math.sin(a) * r * 0.25, rim2, k * 0.7);
    }
  }
}

