    this.w = 34;
    this.facing = -1;
    this.vx = 0;
    this.vy = 0;
    this.state = "spawn";
    this.timer = 1.3;
    this.atkCd = 1.4;
    this.phase = 1;
    this.phaseLock = 1.4;
    this.stun = 0;
    this.freeze = 0;
    this.burn = 0;
    this.burnTick = 0;
    this.burnDmg = 4;
    this.slow = 0;
    this.hitFlash = 0;
    this.dead = false;
    this.auras = {};
