    y: foot3 - height5 / 2,
    depth: foot3,
    hx: (entity.boss ? 14 : Math.max(5, (entity.w ?? 12) * 0.55)) * scale3,
    hy: height5 / 2,
    hd: (entity.boss ? 10 : 6) * scale3
